//! Attack lookups. All tables are generated by `build.rs` and embedded as
//! plain statics, so a lookup is just an index (plus one multiply for sliders).

use crate::types::{Bitboard, Color, PieceType, Square};
use std::mem::transmute;

/// Per-square magic bitboard parameters ("fancy" layout with a shared table).
#[derive(Clone, Copy)]
pub struct Magic {
    pub mask: u64,
    pub magic: u64,
    pub shift: u32,
    pub offset: u32,
}

include!(concat!(env!("OUT_DIR"), "/magics.rs"));

// SAFETY (all three statics): the build script writes exactly this many
// native-endian u64 values; `transmute` checks the sizes at compile time and
// every bit pattern is a valid u64.
static SLIDERS: [u64; SLIDER_TABLE_LEN] =
    unsafe { transmute(*include_bytes!(concat!(env!("OUT_DIR"), "/sliders.bin"))) };

#[repr(C)]
struct Leapers {
    pawn: [[u64; 64]; 2],
    knight: [u64; 64],
    king: [u64; 64],
}

static LEAPERS: Leapers =
    unsafe { transmute(*include_bytes!(concat!(env!("OUT_DIR"), "/leapers.bin"))) };

#[repr(C)]
struct Lines {
    between: [[u64; 64]; 64],
    line: [[u64; 64]; 64],
}

static LINES: Lines =
    unsafe { transmute(*include_bytes!(concat!(env!("OUT_DIR"), "/lines.bin"))) };

/// Squares attacked by a pawn of `color` standing on `sq`.
#[inline(always)]
pub fn pawn_attacks(color: Color, sq: Square) -> Bitboard {
    Bitboard(LEAPERS.pawn[color.idx()][sq.idx()])
}

#[inline(always)]
pub fn knight_attacks(sq: Square) -> Bitboard {
    Bitboard(LEAPERS.knight[sq.idx()])
}

#[inline(always)]
pub fn king_attacks(sq: Square) -> Bitboard {
    Bitboard(LEAPERS.king[sq.idx()])
}

#[inline(always)]
fn slider(magic: &Magic, occ: Bitboard) -> Bitboard {
    let idx = ((occ.0 & magic.mask).wrapping_mul(magic.magic) >> magic.shift) as usize
        + magic.offset as usize;
    debug_assert!(idx < SLIDER_TABLE_LEN);
    // SAFETY: the index is below `offset + 2^bits`, which the build script
    // keeps inside the table for every square.
    Bitboard(unsafe { *SLIDERS.get_unchecked(idx) })
}

#[inline(always)]
pub fn bishop_attacks(sq: Square, occ: Bitboard) -> Bitboard {
    slider(&BISHOP_MAGICS[sq.idx()], occ)
}

#[inline(always)]
pub fn rook_attacks(sq: Square, occ: Bitboard) -> Bitboard {
    slider(&ROOK_MAGICS[sq.idx()], occ)
}

#[inline(always)]
pub fn queen_attacks(sq: Square, occ: Bitboard) -> Bitboard {
    bishop_attacks(sq, occ) | rook_attacks(sq, occ)
}

/// Attacks of a non-pawn piece.
#[inline(always)]
pub fn piece_attacks(pt: PieceType, sq: Square, occ: Bitboard) -> Bitboard {
    match pt {
        PieceType::Knight => knight_attacks(sq),
        PieceType::Bishop => bishop_attacks(sq, occ),
        PieceType::Rook => rook_attacks(sq, occ),
        PieceType::Queen => queen_attacks(sq, occ),
        PieceType::King => king_attacks(sq),
        PieceType::Pawn => unreachable!("pawn attacks depend on colour"),
    }
}

/// Squares strictly between `a` and `b` if they share a rank, file or diagonal; empty otherwise.
#[inline(always)]
pub fn between(a: Square, b: Square) -> Bitboard {
    Bitboard(LINES.between[a.idx()][b.idx()])
}

/// The whole line through `a` and `b` (edge to edge) if they are aligned; empty otherwise.
#[inline(always)]
pub fn line(a: Square, b: Square) -> Bitboard {
    Bitboard(LINES.line[a.idx()][b.idx()])
}

/// Squares attacked by all pawns in `pawns` of the given colour.
#[inline(always)]
pub fn pawn_attacks_bb(color: Color, pawns: Bitboard) -> Bitboard {
    let not_a = pawns.0 & !Bitboard::FILE_A.0;
    let not_h = pawns.0 & !Bitboard::FILE_H.0;
    match color {
        Color::White => Bitboard((not_a << 7) | (not_h << 9)),
        Color::Black => Bitboard((not_a >> 9) | (not_h >> 7)),
    }
}
